/* Visual refinement: a cooler editorial palette with the live readings as the hero. */
:root{--ink:#18343b;--deep:#103640;--deep2:#174751;--sea:#147f83;--mint:#8edac5;--sand:#eef3f1;--paper:#fff;--line:#d7e2df;--muted:#61787d;--coral:#dc8065;--amber:#b98746;--shadow:0 10px 28px rgba(16,54,64,.065)}
body{background:#eef3f1;color:var(--ink)}
.shell{max-width:1360px}
.top{position:sticky;top:0;z-index:1000;background:#103640;border-bottom-color:#ffffff24}
.top .shell{height:64px}
.brand,.meta-top,.eyebrow,.kicker,.metric-label,h1{letter-spacing:0}
.brand{font-size:26px}
.nav{gap:24px}
.hero{background:#123d47}
.hero:before{opacity:.1;background-size:64px 64px}
.hero .shell{min-height:330px;padding-top:36px;padding-bottom:42px}
h1{font-size:58px;line-height:1.08}
.hero p{max-width:500px;color:#c4d7d4}
.hero-art{height:auto;min-height:190px;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;align-items:stretch;padding:18px 0 18px 18px}
.orb{display:none}
.orbit-label{position:relative;inset:auto;display:flex;flex-direction:column;justify-content:space-between;min-width:0;min-height:150px;padding:18px 17px;background:#ffffff0b;border:1px solid #c9e3dc35;border-radius:8px;backdrop-filter:none}
.orbit-label:before{content:"";display:block;width:28px;height:3px;margin-bottom:16px;background:#8edac5}
.orbit-label.one:before{background:#e5997b}
.orbit-label small{font-size:10px;color:#b5d3cc;letter-spacing:0}
.orbit-label strong{font-size:34px;line-height:1.1;font-variant-numeric:tabular-nums}
.badge{border-radius:6px}
.stripe{height:3px;background:#74bca4}
main{padding-top:28px}
.section-head{margin:30px 0 15px}
.section-head h2{font-size:29px;letter-spacing:0}
.section-head p{max-width:620px}
.kicker{color:#287c73;font-size:10px}
.surface{border-radius:8px;border-color:#dce6e3;box-shadow:var(--shadow)}
.pad{padding:24px}
.metrics{gap:10px}
.metrics .metric{min-height:126px;padding:15px 16px;border:1px solid var(--line);border-top:3px solid var(--metric-accent,#147f83);border-radius:8px;box-shadow:0 3px 10px rgba(16,54,64,.025)}
.metrics .metric:nth-child(1){--metric-accent:#297d91}
.metrics .metric:nth-child(2){--metric-accent:#258478}
.metrics .metric:nth-child(3){--metric-accent:#d77b5b}
.metrics .metric:nth-child(4){--metric-accent:#bd8950}
.metrics .metric:nth-child(5){--metric-accent:#668b79}
.metrics .metric b{font-size:28px;font-variant-numeric:tabular-nums}
.metrics .metric>span,.metrics .metric>small{font-size:11px}
.metric-missing{border-top-color:#9baaa7!important;background:#f4f6f4}
.status-line{border-left:3px solid #358b77;border-radius:5px;background:#e5f0ec;padding:10px 14px}
.status-line.alert{border-left-color:#d27759;background:#fff0e9}
.outlook-bar{margin:10px 0 0;padding:10px 14px;border-radius:6px;background:#f4f8f6;border:1px solid var(--line);display:flex;flex-wrap:wrap;gap:8px 20px;font-size:12px;color:#3d5e63}
.outlook-bar strong{color:#183e49;font-weight:650}
.overview-summary{gap:26px;padding:23px 25px;margin-top:16px}
.overview-summary>.window-panel{border-left:1px solid var(--line);padding-left:25px}
.overview-summary h3{font-size:24px;letter-spacing:0}
.text-link{font-weight:650;text-underline-offset:3px}
.tide-window{border-color:#d7e3df;border-radius:7px;background:#f0f6f2;color:#245d57;padding:11px 12px}
.tide-window:hover{background:#e6f1ea;border-color:#9ac6b4}
.tide-window strong{font-size:14px;font-variant-numeric:tabular-nums}
.wide-tide{padding:24px 26px 20px}
.wide-tide .chart-head h3{font-size:22px}
.wide-tide .timeline .past-shade{fill:#eaf5f1}
.wide-tide .timeline .future-shade{fill:#fff2eb}
.wide-tide .timeline .past-line{stroke:#168a88}
.wide-tide .timeline .forecast-line{stroke:#d98261}
